package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.stat.descriptive.univariate.GeometricMean;
import org.apache.commons.math.stat.descriptive.univariate.Mean;
import org.apache.commons.math.stat.descriptive.univariate.Variance;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for SummaryStatistics.addValue
 */
public class SummaryStatistics_addValue_TriageGen5Test {

    private SummaryStatistics stats;

    @Before
    public void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    public void testAddValue_StandardFlow() {
        // Test standard flow where mean, variance, and geoMean are the default implementations
        // (i.e., they ARE instances of Mean, Variance, and GeometricMean respectively)
        // Based on the logic: if (!(meanImpl instanceof Mean)) { increment }
        // To cover the 'if' branches where the condition is FALSE (skipping increment),
        // we use the default implementations.

        double value = 10.0;
        stats.addValue(value);

        Assert.assertEquals(1, stats.getN());
        Assert.assertEquals(value, stats.getSum(), 1e-10);
        Assert.assertEquals(value, stats.getMin(), 1e-10);
        Assert.assertEquals(value, stats.getMax(), 1e-10);
        Assert.assertEquals(value, stats.getMean(), 1e-10);
        Assert.assertEquals(value, stats.getVariance(), 0.0); // Variance of single element is 0 or NaN depending on implementation, but logic check
        Assert.assertEquals(value, stats.getSecondMoment(), 1e-10);
    }

    @Test
    public void testAddValue_CustomImplementations_TriggersIfBranches() {
        // To maximize branch coverage, we need to force the 'if' conditions to be TRUE.
        // This happens when meanImpl is NOT an instance of Mean, etc.

        StorelessUnivariateStatistic mockMean = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockVariance = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockGeoMean = mock(StorelessUnivariateStatistic.class);

        // We must also mock the standard ones to avoid NullPointerException when addValue calls them directly
        StorelessUnivariateStatistic mockSum = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSumSq = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockMin = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockMax = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSumLog = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSecondMoment = mock(StorelessUnivariateStatistic.class);

        stats.setSumImpl(mockSum);
        stats.setSumsqImpl(mockSumSq);
        stats.setMinImpl(mockMin);
        stats.setMaxImpl(mockMax);
        stats.setSumLogImpl(mockSumLog);
        stats.setGeoMeanImpl(mockGeoMean);
        stats.setMeanImpl(mockMean);
        stats.setVarianceImpl(mockVariance);

        // Using a custom second moment implementation if possible, 
        // however, secondMoment is a field incremented directly. 
        // Since we can't set secondMoment directly via setter in the provided API, 
        // we rely on the existing object behavior or assume it's initialized.
        // But the code shows: secondMoment.increment(value). 
        // In SummaryStatistics, secondMoment is usually an internal object.

        // We need to ensure the custom mocks are NOT instances of Mean/Variance/GeometricMean
        // to enter the if blocks.

        double value = 5.0;
        stats.addValue(value);

        // Verify standard increments
        verify(mockSum, times(1)).increment(value);
        verify(mockSumSq, times(1)).increment(value);
        verify(mockMin, times(1)).increment(value);
        verify(mockMax, times(1)).increment(value);
        verify(mockSumLog, times(1)).increment(value);

        // Verify the conditional increments (the 'if' branches)
        verify(mockMean, times(1)).increment(value);
        verify(mockVariance, times(1)).increment(value);
        verify(mockGeoMean, times(1)).increment(value);

        Assert.assertEquals(1, stats.getN());
    }

    @Test
    public void testAddValue_SkipConditionalIncrements() {
        // To cover the case where the 'if' condition is FALSE (meaning they ARE instances of Mean/Variance/GeoMean)
        // We use real implementations that satisfy the 'instanceof' check.

        Mean realMean = new Mean();
        Variance realVariance = new Variance();
        GeometricMean realGeoMean = new GeometricMean();

        stats.setMeanImpl(realMean);
        stats.setVarianceImpl(realVariance);
        stats.setGeoMeanImpl(realGeoMean);

        double value = 2.0;
        stats.addValue(value);

        // If the condition (!(meanImpl instanceof Mean)) is false, increment is NOT called on the mock.
        // Here we verify the values are updated via the real implementation.
        Assert.assertEquals(value, stats.getMean(), 1e-10);
        Assert.assertEquals(value, stats.getVariance(), 0.0);
        Assert.assertEquals(1, stats.getN());
    }

    @Test
    public void testAddValue_MultipleValues() {
        stats.addValue(1.0);
        stats.addValue(2.0);
        stats.addValue(3.0);

        Assert.assertEquals(3, stats.getN());
        Assert.assertEquals(6.0, stats.getSum(), 1e-10);
        Assert.assertEquals(2.0, stats.getMean(), 1e-10);
        Assert.assertEquals(1.0, stats.getMin(), 1e-10);
        Assert.assertEquals(3.0, stats.getMax(), 1e-10);
    }
}
